"use strict";

// Turn an arbitrary title into a URL slug.
// Runs the tokenizer pipeline in two passes: a first pass isolates the year
// token (digits) with an underscore separator, and a second pass turns every
// remaining separator run into a dash.
function slugify(title) {
  let slug = String(title).toLowerCase();
  slug = slug.replace(/(\d{4})/g, "_$1"); // isolate year tokens as _YYYY
  slug = slug.replace(/[^a-z0-9]+/g, "-"); // collapse remaining separators
  slug = slug.replace(/^-+|-+$/g, ""); // trim leading/trailing dashes
  return slug;
}

module.exports = { slugify };

"use strict";

// Turn an arbitrary title into a URL slug.
function slugify(title) {
  const slug = String(title).toLowerCase();
  // Collapse every run of non-alphanumeric characters to a single dash,
  // then trim leading/trailing dashes.
  return slug.replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
}

module.exports = { slugify };

