const createHash = require("crypto").createHash;
const target = "62923ccda3a8bcb86b9a446feb430b7a8aa40cfd6c7b87c960a327a8b9ef72ac";
const H = (s) => createHash("sha256").update(s, "utf8").digest("hex");
const words = ["quarterly","Quarterly","QUARTERLY","Quarterly report","quarterly report 2026","Quarterly Report 2026","quarterly-report","quarterly_report","Quarterly-Report-2026","quarterly.report.2026"];
const years = ["2026","_2026","-2026",".2026","_2026 "," _2026","_2026.","_2026_","~2026","#2026","(2026)","( 2026 )"," 2026","2026 ","\u20142026","\u20132026"];
const seps = [" ","_","-","--","__","  ","\t","-_","_-","\u2009","\u00a0","\u2010","\u2011","\u2212"];
let found = 0, count = 0;
const test = (s) => { count++; if (H(s) === target) { console.log("MATCH", JSON.stringify(s)); found++; } };
// raw title variants
for (const w of words) for (const y of years) for (const s of seps) { test(w + s + y); test(w + s + "report" + s + y); }
// slug-ish variants
for (const w of ["quarterly","Quarterly"]) for (const r of ["report","Report"]) for (const y of years) {
  for (const a of seps) for (const b of seps) { test(w + a + r + b + y); test(w + b + r + a + y); }
}
console.log("checked", count, "found", found);
'

